import {registerCatalog,localizedText} from './i18n.js';
import {displayNumber} from './number-display.js';
const pairs={title:['Dated USD / ADS translation','日期匹配的美元／ADS 换算'],scope:['September 30, 2026 conditional allocation. This is not a current USD target or market-price comparison.','2026 年 9 月 30 日的条件估计分配。这不是当前美元目标价，也不用于市价比较。'],formula:['TWD {native} per ordinary share × 5 ÷ 31.880 TWD per USD = USD {ads} per ADS.','每普通股 {native} 新台币 × 5 ÷ 每美元 31.880 新台币 = 每 ADS {ads} 美元。'],limits:['Original claims, dilution and date limitations remain. The long-term interest-bearing debt subtotal includes more than bonds; overlap with the retained lease sensitivity has not been resolved.','原有索偿、稀释和日期限制仍适用。长期有息负债小计不仅包含债券；它与保留的租赁敏感性调整是否重叠，尚未解决。'],source:['Spot FX and ADS ratio: original quarterly statements, pages 1–2','即期汇率及 ADS 比例：原始季度报表第 1–2 页'],shares:['Outstanding shares and debt subtotal: quarterly presentation, slide 7','流通股数及债务小计：季度简报第 7 页'],unknown:['Dated USD / ADS translation unavailable: restore the reviewed September 30 TWD ordinary-share case and its matched capital date.','日期匹配的美元／ADS 换算不可用：请恢复已审核的 9 月 30 日新台币普通股方案及匹配的资本日期。']};
registerCatalog('tsmDatedADS',{en:Object.fromEntries(Object.entries(pairs).map(([k,v])=>[k,v[0]])),'zh-Hans':Object.fromEntries(Object.entries(pairs).map(([k,v])=>[k,v[1]]))});
export function tsmDatedConversionHTML(bridge){
 const r=bridge?.datedADSConversion;if(!r)return '';
 if(r.status!=='dated-conditional-conversion')return `<p class="research-warning" id="tsm-dated-ads">${localizedText('tsmDatedADS.unknown')}</p>`;
 return `<section class="research-card" id="tsm-dated-ads"><h3>${localizedText('tsmDatedADS.title')}</h3><p class="research-equity-value">${displayNumber(r.perADS,2)} USD / ADS</p><p>${localizedText('tsmDatedADS.scope')}</p><p>${localizedText('tsmDatedADS.formula',{native:displayNumber(r.nativePerShare,2),ads:displayNumber(r.perADS,2)})}</p><p class="micro">${localizedText('tsmDatedADS.limits')}</p><p><a href="${r.sources[0].url}" target="_blank" rel="noopener">${localizedText('tsmDatedADS.source')}</a></p><p><a href="${r.sources[2].url}" target="_blank" rel="noopener">${localizedText('tsmDatedADS.shares')}</a></p></section>`;
}
